; Attributes: bp-based frame

                public is_disp8n
is_disp8n       proc near

disp8           = dword ptr -0Ch
n               = byte ptr -5
off             = dword ptr -4
input           = dword ptr  8
ins             = dword ptr  0Ch
compdisp        = dword ptr  10h

                push    ebp             ; /* Check if offset is a multiple of N with corresponding tuple type
