                mov     ebp, esp        ; bool is_disp8n(operand *input, insn *ins, int8_t *compdisp)
                sub     esp, 12
                nop
                mov     eax, [ebp+input]
                add     eax, 40         ; int64_t offset;
                mov     ecx, [eax]
                add     eax, 4
                mov     edx, [eax]
                mov     [ebp+off], ecx  ; int32_t off = input->offset;
                mov     eax, [ebp+ins]
